  ?zone a brick:Zone ; brick:hasNameOptional ?zoneName .
  FILTER(?zoneName = ref:"Zone_F3_Z01" || str(?zone) = "Zone_F3_Z01")
}

SELECT ?z ?name WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z brick:hasNameOptional ?name }
}

