import csv
from collections import defaultdict
cat = list(csv.reader(open(CATALOG_CSV)))[1:]
catmap = {r[0]:(r[1].rsplit('/',1)[-1], r[2]) for r in cat}
data = defaultdict(dict)
for tsid, ts, v in list(csv.reader(open(VALUES_CSV)))[1:]:
    try: data[tsid][ts] = float(v)
    except: pass

def stat(tsid):
    d = data[tsid]
    before = [v for ts,v in d.items() if ts < '2018-07-01']
    after = [v for ts,v in d.items() if ts >= '2018-07-01']
    b = sum(before)/len(before) if before else None
    a = sum(after)/len(after) if after else None
    return b,a

# print setpoints and sensor for all zones for July 2018 onward and before
for cls in ('Zone_Air_Temperature_Sensor','Zone_Air_Cooling_Temperature_Setpoint','Zone_Air_Heating_Temperature_Setpoint'):
    print("==",cls)
    for tid,(nm,cc) in sorted(catmap.items(), key=lambda x:x[1][0]):
        if cc==cls:
            b,a=stat(tid)
            print(f"  {nm:60s} before={b and round(b,2)} after={a and round(a,2)}")
